import Foundation
import XCTest

@testable import WealthOneCore

final class LegacyNullableAmountsTests: XCTestCase {
  private let plain =
    #"{"accounts":[{"id":"a","name":"Example savings","isAsset":true,"accountType":0}],"records":[{"date":"2026-10-01","totals":[{"id":"a","amount":null}],"inflows":[{"id":"a","amount":null}],"outflows":[{"id":"a","amount":0}]},{"date":"2026-10-02","totals":[{"id":"a","amount":123.45}],"inflows":[{"id":"a","amount":0.03}],"outflows":[]}],"goal":{"pension":0.03}}"#
  // Synthetic fixture generated by the installed lz-string, never a private backup.
  private let compressed =
    ""

  func testLegacyNullAmountsAreUnrecordedWhileZeroAndDecimalsSurvive() throws {
    let snapshot = try LegacyReduxDecoder.decode(plain)
    XCTAssertEqual(snapshot.records.count, 2)
    XCTAssertNil(snapshot.records[0].totals["a"])
    XCTAssertNil(snapshot.records[0].inflows["a"])
    XCTAssertEqual(snapshot.records[0].outflows["a"], 0)
    XCTAssertEqual(snapshot.records[1].totals["a"], Decimal(string: "123.45"))
    XCTAssertEqual(snapshot.records[1].inflows["a"], Decimal(string: "0.03"))
    XCTAssertEqual(snapshot.goal["pension"], .decimal(Decimal(string: "0.03")!))
  }
  func testCompressedAndPlainCopiesRecoverAndExportsRoundTrip() throws {
    let raw = String(decoding: try XCTUnwrap(Data(base64Encoded: compressed)), as: UTF8.self)
    let report = LegacyRecoveryReport.scan([
      "persist:wealthone_data": raw, "wealthone": plain, "backup": plain,
    ])
    XCTAssertTrue(report.unreadableSources.isEmpty)
    XCTAssertEqual(report.candidates.count, 3)
    for candidate in report.candidates {
      XCTAssertEqual(candidate.snapshot.records[1].inflows["a"], Decimal(string: "0.03"))
      XCTAssertEqual(candidate.snapshot.goal["pension"], .decimal(Decimal(string: "0.03")!))
      XCTAssertEqual(
        try Archive.snapshot(from: candidate.archive), try LegacyReduxDecoder.decode(plain))
    }
  }
  func testNativeRecoveredArchivePreservesExactDecimalPrecision() throws {
    struct Baseline: Encodable {
      let version = 1
      let snapshot: Snapshot
    }
    let value = Decimal(string: "1234567890.123456789012345")!
    let original = Snapshot(
      accounts: [Account(id: "a", name: "Example")],
      records: [
        DayRecord(
          date: "2026-10-01", totals: ["a": value], inflows: ["a": Decimal(string: "0.03")!])
      ],
      goal: ["pension": .decimal(Decimal(string: "0.123456789012345678")!)])
    let data = try JSONEncoder().encode(Baseline(snapshot: original))
    XCTAssertEqual(try Archive.snapshot(from: data), original)
  }

  func testNullSupportDoesNotAcceptAmbiguousOrInvalidEntries() {
    for value in [
      #"[{"id":"a","amount":true}]"#,
      #"[{"id":"a"}]"#,
      #"[{"id":"unknown","amount":null}]"#,
      #"[{"id":"a","amount":null},{"id":"a","amount":10}]"#,
    ] {
      let raw =
        #"{"accounts":[{"id":"a","name":"Example","isAsset":true}],"records":[{"date":"2026-10-01","totals":REPLACE}]}"#
        .replacingOccurrences(of: "REPLACE", with: value)
      XCTAssertThrowsError(try Archive.snapshot(from: Data(raw.utf8)))
    }
  }
}
